def main():
    seasons=[]
    for title,background,rows in SEASONS:
        episodes=[]
        for row in rows.strip().splitlines():
            name,clue,reveal,amara,hook=row.split('|')
            episodes.append(dict(title=name,clue=clue,
                setup=f"The next lead is {clue}. We need its original source before Victor moves again.",
                reveal=reveal,amara=amara,hook=hook))
        assert len(episodes)==10
        seasons.append(dict(title=title,background=background,episodes=episodes))
    path=Path(__file__).resolve().parents[1]/'configs/story_campaign.json'
    path.write_text(json.dumps(dict(version=1,first_level=51,episode_length=10,seasons=seasons),indent=2)+'\n',encoding='utf-8')


if __name__=='__main__':
    main()
